// @generated by:gauntlet run:godseye-local-broker
import { randomBytes, randomUUID } from "node:crypto";
import {
  AccessOverview,
  AccessSlotView,
  CONTROL_API_HEADER,
  CONTROL_API_VERSION,
  ProjectResponse,
  ServiceIdentityView,
} from "@godseye/contracts";
import { AccessBroker, FoundationEngine } from "@godseye/core";
import { afterEach, beforeEach, describe, expect, it } from "vitest";
import { createApp } from "../apps/control-api/src/app.js";
import { loadConfiguration } from "../apps/control-api/src/config.js";
import { MemoryAccessProvider } from "./access-helpers.js";
import { projectInput } from "./helpers.js";
import { type OwnerAuthFixture, ownerAuthFixture } from "./owner-auth-fixture.js";

describe("metadata-only owner service access HTTP", () => {
  let fixture: OwnerAuthFixture;
  let app: ReturnType<typeof createApp>;
  let broker: AccessBroker;
  let provider: MemoryAccessProvider;
  let headers: Headers;

  beforeEach(async () => {
    fixture = await ownerAuthFixture();
    // This provider models first-party HTTP boundaries only; OpenBao has its own real lab.
    provider = new MemoryAccessProvider();
    const engine = new FoundationEngine(fixture.store);
    broker = new AccessBroker(fixture.store, {
      foundation: engine,
      provider,
      fingerprintKey: randomBytes(48).toString("base64url"),
    });
    app = createApp(
      fixture.core,
      loadConfiguration({ GODSEYE_MODE: "local" }),
      fixture.identity,
      engine,
      broker,
    );
    headers = (await fixture.session()).headers;
    headers.set(CONTROL_API_HEADER, CONTROL_API_VERSION);
  });
  afterEach(async () => fixture.close());

  function request(path: string, method = "GET", body?: unknown, key = randomUUID()) {
    const requestHeaders = new Headers(headers);
    if (method !== "GET") requestHeaders.set("idempotency-key", key);
    return app.request(new URL(`/api/v1${path}`, fixture.origin), {
      method,
      headers: requestHeaders,
      ...(body === undefined ? {} : { body: JSON.stringify(body) }),
    });
  }

  async function project(slug = projectInput.slug) {
    const response = await request("/projects", "POST", { ...projectInput, slug });
    expect(response.status).toBe(201);
    return ProjectResponse.parse(await response.json());
  }

  async function input(slug = projectInput.slug) {
    const saved = await project(slug);
    const environment = saved.environments[0];
    if (!environment) throw new Error("Missing HTTP fixture environment");
    return {
      projectId: saved.id,
      environmentId: environment.id,
      purpose: "runtime" as const,
      name: "HTTP runtime identity",
    };
  }

  async function identity() {
    const response = await request("/access/identities", "POST", await input());
    expect(response.status).toBe(201);
    return ServiceIdentityView.parse(await response.json());
  }

  it("T-AC-14 requires an owner session for every access route before mutation validation", async () => {
    const id = randomUUID();
    for (const [method, path] of [
      ["GET", "/access"],
      ["POST", "/access/identities"],
      ["POST", "/access/slots"],
      ["POST", `/access/identities/${id}/revoke`],
      ["POST", `/access/slots/${id}/activate`],
      ["POST", `/access/operations/${id}/reconcile`],
    ]) {
      const response = await app.request(new URL(`/api/v1${path}`, fixture.origin), {
        method,
        headers: fixture.headers(),
        ...(method === "GET" ? {} : { body: "{}" }),
      });
      expect(response.status).toBe(401);
    }
    expect(
      (await broker.overview({ id: fixture.identity.ownerId, kind: "owner", projectIds: [] }))
        .identities,
    ).toHaveLength(0);
  });

  it("T-AC-15 cannot use a genuine service proof to authenticate owner or project administration", async () => {
    const saved = await identity();
    const actor = await fixture.identity.actor(headers);
    if (!actor) throw new Error("Missing owner fixture actor");
    let proof = "";
    await broker.issueProof(actor, saved.id, saved.revision, randomUUID(), (value) => {
      proof = value;
    });

    for (const path of ["/access", "/projects", "/owner/security"]) {
      const response = await app.request(new URL(`/api/v1${path}`, fixture.origin), {
        headers: fixture.headers({ authorization: `Bearer ${proof}` }),
      });
      expect(response.status).toBe(401);
    }
  });

  it("T-AC-14 refuses a project and environment pair from different registered projects", async () => {
    const first = await input();
    const second = await project("other-http-cell");

    const response = await request("/access/identities", "POST", {
      ...first,
      projectId: second.id,
    });

    expect(response.status).toBe(403);
    expect(AccessOverview.parse(await (await request("/access")).json()).identities).toHaveLength(
      0,
    );
  });

  it("T-AC-14 rejects caller-supplied authority instead of widening the identity schema", async () => {
    const response = await request("/access/identities", "POST", {
      ...(await input()),
      actor: { id: fixture.identity.ownerId, kind: "owner" },
    });

    expect(response.status).toBe(422);
    expect(AccessOverview.parse(await (await request("/access")).json()).identities).toHaveLength(
      0,
    );
  });

  it("T-AC-14 requires recent passkey verification before creating service authority", async () => {
    const data = await input();
    headers = (await fixture.session(6 * 60_000)).headers;

    const response = await request("/access/identities", "POST", data);

    expect(response.status).toBe(403);
    expect(await response.json()).toMatchObject({ error: { code: "STEP_UP_REQUIRED" } });
  });

  it("T-AC-14 converges identical keyed creations and rejects a changed identity under that key", async () => {
    const data = await input();
    const key = randomUUID();
    const responses = await Promise.all([
      request("/access/identities", "POST", data, key),
      request("/access/identities", "POST", data, key),
    ]);
    const saved = await Promise.all(
      responses.map(async (response) => ServiceIdentityView.parse(await response.json())),
    );
    expect(responses.map((response) => response.status)).toEqual([201, 201]);
    const [first, second] = saved;
    if (!first || !second) throw new Error("Missing keyed creation responses");
    expect(first.id).toBe(second.id);

    const changed = await request(
      "/access/identities",
      "POST",
      { ...data, name: "Changed identity" },
      key,
    );

    expect(changed.status).toBe(409);
    expect(AccessOverview.parse(await (await request("/access")).json()).identities).toHaveLength(
      1,
    );
  });

  it("T-AC-14 refuses stale identity revocation without changing the accepted revision", async () => {
    const saved = await identity();
    const stale = await request(`/access/identities/${saved.id}/revoke`, "POST", {
      expectedRevision: saved.revision + 1,
    });
    expect(stale.status).toBe(409);
    const unchanged = AccessOverview.parse(await (await request("/access")).json()).identities[0];
    expect(unchanged).toMatchObject({ status: "active", revision: saved.revision });

    const accepted = await request(`/access/identities/${saved.id}/revoke`, "POST", {
      expectedRevision: saved.revision,
    });

    expect(accepted.status).toBe(200);
    expect(ServiceIdentityView.parse(await accepted.json())).toMatchObject({
      status: "revoked",
      revision: saved.revision + 1,
    });
  });

  it("T-AC-14 keeps privately issued proof and staged material out of metadata and audit responses", async () => {
    const saved = await identity();
    const response = await request("/access/slots", "POST", {
      identityId: saved.id,
      name: "Runtime material",
    });
    const slot = AccessSlotView.parse(await response.json());
    const actor = await fixture.identity.actor(headers);
    if (!actor) throw new Error("Missing owner fixture actor");
    let proof = "";
    const material = randomBytes(32).toString("base64url");
    await broker.issueProof(actor, saved.id, saved.revision, randomUUID(), (value) => {
      proof = value;
    });
    await broker.stage(
      actor,
      { slotId: slot.id, expectedRevision: slot.revision },
      material,
      randomUUID(),
    );

    const metadataResponse = await request("/access");
    const metadata = await metadataResponse.text();
    const audit = await (await request("/audit")).text();

    expect(metadataResponse.headers.get(CONTROL_API_HEADER)).toBe(CONTROL_API_VERSION);
    expect(AccessOverview.safeParse(JSON.parse(metadata)).success).toBe(true);
    for (const text of [metadata, audit]) {
      expect(text.includes(material)).toBe(false);
      expect(text.includes(proof)).toBe(false);
      expect(/proofDigest|materialFingerprint|fingerprintKey/.test(text)).toBe(false);
    }
    expect(AccessOverview.parse(JSON.parse(metadata)).slots[0]).toMatchObject({
      state: "staged",
      stagedVersion: 1,
    });
  });

  it("T-AC-14 bounds an invalid producer response without echoing unexpected material", async () => {
    const marker = randomBytes(32).toString("base64url");
    const original = broker.overview.bind(broker);
    broker.overview = async (actor) => ({ ...(await original(actor)), material: marker });

    const response = await request("/access");
    const text = await response.text();

    expect(response.status).toBe(500);
    expect(text.length).toBeLessThan(1024);
    expect(text.includes(marker)).toBe(false);
    expect(JSON.parse(text)).toMatchObject({ error: { code: "INTERNAL_ERROR" } });
  });

  it("T-AC-14 returns visible sealed state without exposing provider authority", async () => {
    provider.state = "sealed";

    const response = await request("/access");

    expect(response.status).toBe(200);
    expect(AccessOverview.parse(await response.json())).toEqual({
      provider: { state: "sealed" },
      identities: [],
      slots: [],
      operations: [],
      adapters: [],
    });
  });

  it("T-AC-14 refuses activation when no qualified transition adapter is registered", async () => {
    const saved = await identity();
    const response = await request("/access/slots", "POST", {
      identityId: saved.id,
      name: "Unqualified target",
    });
    const slot = AccessSlotView.parse(await response.json());

    const activation = await request(`/access/slots/${slot.id}/activate`, "POST", {
      expectedRevision: slot.revision,
      adapterId: "caller-invented",
    });

    expect(activation.status).toBe(503);
    expect(AccessOverview.parse(await (await request("/access")).json()).operations).toHaveLength(
      0,
    );
  });

  it("T-AC-14 exposes no owner HTTP value or authentication-proof reveal route", async () => {
    const id = randomUUID();
    for (const path of [`/access/slots/${id}/value`, `/access/identities/${id}/proof`]) {
      const response = await request(path);
      expect(response.status).toBe(404);
    }
  });
});
